    long long n;
    cin >> n;
    vector<long long> prices(n);
    for (int i = 0; i < n; i++) cin >> prices[i];

    long long b1 = -1000000000000000000LL, b2 = -1000000000000000000LL, s1 = 0, s2 = 0;
    for (long long p : prices) {
        b1 = max(b1, -p);
        s1 = max(s1, b1 + p);
        b2 = max(b2, s1 - p);
        s2 = max(s2, b2 + p);
    }
    cout << s2 << "\n";

    return 0;
}

